# integration a3cf7ec). fit: 'yes' | 'partial' | 'no'.
import json, sys
I = 'src/assets/ui_icons/'
def a(id, es, en, who, what, now, used, fit, why, icon=True, extra=None):
    d = dict(id=id, es=es, en=en, who=who, what=what, now=now, sheets_used=used, fit=fit, why=why,
             icon=(I + id + '.png') if icon is True else icon)
    if extra: d.update(extra)
    return d
